	('1a152593-97a8-4954-b2a3-97c50573d0c9', '11f32aae-ea08-47e0-8114-f5d8a900c9a1', '96bd97a7-b948-4c05-9d24-23dbbf8cb05a', 'update', 'contract_parameter_values', 'c31578ca-a36d-401c-8d92-3e069304aa3a', '{"id": "c31578ca-a36d-401c-8d92-3e069304aa3a", "campo": "escopo_resumo", "grupo": "objeto", "label": "Resumo do escopo aprovado", "ordem": 40, "valor": null, "origem": null, "status": "vazio", "conflito": [], "created_at": "2026-08-17T00:07:39.939246+00:00", "created_by": "96bd97a7-b948-4c05-9d24-23dbbf8cb05a", "updated_at": "2026-08-17T19:43:48.631741+00:00", "updated_by": "96bd97a7-b948-4c05-9d24-23dbbf8cb05a", "archived_at": null, "archived_by": null, "obrigatorio": true, "atualizado_em": "2026-08-17T19:43:48.631741+00:00", "justificativa": null, "parameters_id": "226234d5-0a9c-4572-bfa9-f97ce20c1a29", "archive_reason": null, "atualizado_por": "96bd97a7-b948-4c05-9d24-23dbbf8cb05a", "origem_detalhe": null, "organization_id": "11f32aae-ea08-47e0-8114-f5d8a900c9a1"}', '{"id": "c31578ca-a36d-401c-8d92-3e069304aa3a", "campo": "escopo_resumo", "grupo": "objeto", "label": "Resumo do escopo aprovado", "ordem": 40, "valor": "A proposta familiar está pronta para avançar com Ana Luiza, pai e irmã na mesma jornada documental.  Com a definição do plano, seguimos para a formalização da contratação e o início da jornada, com direção estratégica, acompanhamento próximo e clareza em cada próxima etapa.  O investimento total é de R$ 9.600, dividido em três assinaturas mensais de R$ 320 por responsável, durante 10 meses. Cada assinatura termina automaticamente após a 10ª cobrança.  Certidões, traduções, apostilas e taxas não estão incluídas nos honorários, salvo previsão expressa. Os valores são estimados e aprovados antes de cada contratação, com pagamento direto ou provisão antecipada e comprovantes.  Após a jornada contratada, serviços de pós-cidadania — como certificado, passaporte, identidade e registros civis — serão avaliados individualmente como extensão, sem renovação automática.", "origem": "preenchimento_humano", "status": "importado_a_confirmar", "conflito": [], "created_at": "2026-08-17T00:07:39.939246+00:00", "created_by": "96bd97a7-b948-4c05-9d24-23dbbf8cb05a", "updated_at": "2026-08-17T20:36:43.022263+00:00", "updated_by": "96bd97a7-b948-4c05-9d24-23dbbf8cb05a", "archived_at": null, "archived_by": null, "obrigatorio": true, "atualizado_em": "2026-08-17T20:36:43.022263+00:00", "justificativa": null, "parameters_id": "226234d5-0a9c-4572-bfa9-f97ce20c1a29", "archive_reason": null, "atualizado_por": "96bd97a7-b948-4c05-9d24-23dbbf8cb05a", "origem_detalhe": "", "organization_id": "11f32aae-ea08-47e0-8114-f5d8a900c9a1"}', NULL, '2026-08-17 20:36:43.022263+00'),
