	('7c155397-53cb-47e8-af18-ffcceffa8a2e', '11f32aae-ea08-47e0-8114-f5d8a900c9a1', 'CA-WPP-002', 'Pacote WhatsApp Premium', 'acompanhamento', 'complemento', 'TOP_30', 'homologado', false, 119.00, NULL, 'Conforme catálogo homologado', 'Acompanhamento ampliado por WhatsApp dentro do escopo aprovado.', true, true, '2026-08-20 01:00:18.178042+00', NULL, '2026-08-22 16:17:26.935372+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', true, true, false, 'Representa oferta e escopo aprovado. Não ativa mensagem automática nem automação de canal.', 'ativo', 'OFICIAL-2/2b0a6512abdf641f', NULL, NULL, NULL, 'pendente', 'Fora da base comercial Top 30. Preservado como histórico e uso interno; não entra no seletor de proposta. [Bloqueado por validação comercial: preço, escopo ou link divergente.]', NULL, NULL, NULL, false, NULL, 'TOP_30', 'CA · FIN · Planilha Mestre de Produtos OFICIAL 2.xlsx', 'Catalogo Produtos', 'OFICIAL-2/2b0a6512abdf641f', 82, 'TOP_PARETO', 'WhatsApp Familiar', 'Conexão Familiar', 'F4 – Memória', 'Venda Unica', 'Pacote premium de conexão familiar via WhatsApp', 'App / WhatsApp', 'BRL', 149.00, 119.00, 'Ativo', NULL, 'pendente_criar_link', NULL, '2026-08-22 16:17:26.935372+00', 'rascunho', 'cauda_longa', NULL, NULL, 'sob_consulta', '[]', '[]', '[]', '[]', '[]', '[]', '[]', NULL, 'nao_homologado', NULL, 'v1', NULL, NULL, NULL, 'nao_reconciliado', false, NULL, NULL),
	('364319e7-c76c-46c3-a704-bee6ff604773', 'b0fa3d42-43f4-4c7a-b942-11520e40cdd9', 'CA-WPP-002', 'Pacote WhatsApp Premium', 'acompanhamento', 'complemento', 'TOP_30', 'homologado', false, 119.00, NULL, 'Conforme catálogo homologado', 'Acompanhamento ampliado por WhatsApp dentro do escopo aprovado.', true, true, '2026-08-20 01:00:18.178042+00', NULL, '2026-08-22 16:17:26.935372+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', true, true, false, 'Representa oferta e escopo aprovado. Não ativa mensagem automática nem automação de canal.', 'ativo', 'OFICIAL-2/2b0a6512abdf641f', NULL, NULL, NULL, 'pendente', 'Fora da base comercial Top 30. Preservado como histórico e uso interno; não entra no seletor de proposta. [Bloqueado por validação comercial: preço, escopo ou link divergente.]', NULL, NULL, NULL, false, NULL, 'TOP_30', 'CA · FIN · Planilha Mestre de Produtos OFICIAL 2.xlsx', 'Catalogo Produtos', 'OFICIAL-2/2b0a6512abdf641f', 82, 'TOP_PARETO', 'WhatsApp Familiar', 'Conexão Familiar', 'F4 – Memória', 'Venda Unica', 'Pacote premium de conexão familiar via WhatsApp', 'App / WhatsApp', 'BRL', 149.00, 119.00, 'Ativo', NULL, 'pendente_criar_link', NULL, '2026-08-22 16:17:26.935372+00', 'rascunho', 'cauda_longa', NULL, NULL, 'sob_consulta', '[]', '[]', '[]', '[]', '[]', '[]', '[]', NULL, 'nao_homologado', NULL, 'v1', NULL, NULL, NULL, 'nao_reconciliado', false, NULL, NULL),
	('432257e6-9f7d-43d7-bf1d-ac2ec12431c1', '11f32aae-ea08-47e0-8114-f5d8a900c9a1', 'CA-CID-006', 'Combo Codice + SPID', NULL, 'complemento', 'TOP_30', 'em_revisao', false, 280.00, NULL, NULL, NULL, true, true, '2026-08-21 13:34:40.158175+00', NULL, '2026-08-22 18:39:02.077079+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', false, false, false, NULL, 'ativo', 'OFICIAL-2/2b0a6512abdf641f', NULL, NULL, NULL, 'validado', 'Decisão inicial de governança: preço comercial vigente de referência R$ 280. Permanece Em revisão até validação do link Asaas e homologação explícita. Não pode entrar em proposta, contrato, cobrança ou onboarding.', 'pos_reconhecimento', NULL, NULL, false, 'Complemento pós-cidadania', 'TOP_30', 'CA · FIN · Planilha Mestre de Produtos OFICIAL 2.xlsx', 'Catalogo Produtos', 'OFICIAL-2/2b0a6512abdf641f', 7, 'TOP_PARETO', 'Cidadania Italiana', 'Documentos Avulsos', 'F3 – Documentos / Burocracia', 'Bundle', 'Codice Fiscale + SPID com desconto', 'WhatsApp Direto', 'BRL', 280.00, 249.00, 'Ativo', 'https://www.asaas.com/c/nckx16l6u66myjrt', 'link_criado', NULL, '2026-08-22 16:17:26.935372+00', 'rascunho', 'cauda_longa', NULL, NULL, 'sob_consulta', '[]', '[]', '[]', '[]', '[]', '[]', '[]', NULL, 'nao_homologado', NULL, 'v1', NULL, NULL, NULL, 'nao_reconciliado', false, NULL, NULL),
	('22b3f2af-abeb-441b-ad6b-0bb2550c7a06', '0343f7b0-d538-4687-ad9a-68196eb1ff83', 'CA-MEM-003', 'Entrevista Guiada com Idoso', NULL, 'produto_pai', 'TOP_30', 'em_revisao', false, 297.00, NULL, NULL, NULL, true, true, '2026-08-22 16:17:26.935372+00', NULL, '2026-08-22 18:39:02.077079+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Planilha Mestre linha 14', '{}', false, false, false, NULL, 'ativo', 'OFICIAL-2/2b0a6512abdf641f', NULL, NULL, NULL, 'validado', 'Decisão inicial de governança: preço comercial vigente de referência R$ 297. Permanece Em revisão até validação do link Asaas e homologação explícita. Não pode entrar em proposta, contrato, cobrança ou onboarding.', NULL, NULL, NULL, false, NULL, 'TOP_30', 'CA · FIN · Planilha Mestre de Produtos OFICIAL 2.xlsx', 'Catalogo Produtos', 'OFICIAL-2/2b0a6512abdf641f', 14, 'TOP_PARETO', 'Memoria Familiar', 'Entrevistas', 'F5 – Memória / Legado / Presentes / Conteúdo', 'Venda Unica', 'Sessao estruturada para capturar historias de vida', 'WhatsApp Direto', 'BRL', 297.00, 197.00, 'Ativo', 'https://www.asaas.com/c/nufu1fsxm2zr9yks', 'link_criado', NULL, '2026-08-22 16:17:26.935372+00', 'rascunho', 'cauda_longa', NULL, NULL, 'sob_consulta', '[]', '[]', '[]', '[]', '[]', '[]', '[]', NULL, 'nao_homologado', NULL, 'v1', NULL, NULL, NULL, 'nao_reconciliado', false, NULL, NULL),
	('2df7dc42-2488-43a2-81f7-360d0d3468de', 'b0fa3d42-43f4-4c7a-b942-11520e40cdd9', 'CA-MEM-003', 'Entrevista Guiada com Idoso', NULL, 'produto_pai', 'TOP_30', 'em_revisao', false, 297.00, NULL, NULL, NULL, true, true, '2026-08-22 16:17:26.935372+00', NULL, '2026-08-22 18:39:02.077079+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Planilha Mestre linha 14', '{}', false, false, false, NULL, 'ativo', 'OFICIAL-2/2b0a6512abdf641f', NULL, NULL, NULL, 'validado', 'Decisão inicial de governança: preço comercial vigente de referência R$ 297. Permanece Em revisão até validação do link Asaas e homologação explícita. Não pode entrar em proposta, contrato, cobrança ou onboarding.', NULL, NULL, NULL, false, NULL, 'TOP_30', 'CA · FIN · Planilha Mestre de Produtos OFICIAL 2.xlsx', 'Catalogo Produtos', 'OFICIAL-2/2b0a6512abdf641f', 14, 'TOP_PARETO', 'Memoria Familiar', 'Entrevistas', 'F5 – Memória / Legado / Presentes / Conteúdo', 'Venda Unica', 'Sessao estruturada para capturar historias de vida', 'WhatsApp Direto', 'BRL', 297.00, 197.00, 'Ativo', 'https://www.asaas.com/c/nufu1fsxm2zr9yks', 'link_criado', NULL, '2026-08-22 16:17:26.935372+00', 'rascunho', 'cauda_longa', NULL, NULL, 'sob_consulta', '[]', '[]', '[]', '[]', '[]', '[]', '[]', NULL, 'nao_homologado', NULL, 'v1', NULL, NULL, NULL, 'nao_reconciliado', false, NULL, NULL);
INSERT INTO public.case_services VALUES
	('34137bee-67da-4600-9306-4287542b1652', '11f32aae-ea08-47e0-8114-f5d8a900c9a1', 'a11a0000-0000-4000-8000-000000000002', '3d7d57b3-6010-42be-8e72-c146c4d6527e', 'bffdfb48-d22a-4c33-8011-f3c8e96a6e6a', 'Escopo derivado da proposta Canva conferida (deck interno DECK-CANVA-CA-CID-AT-FAM-2026-001-v1, páginas 1–7): diagnóstico familiar multipaís com linha prioritária Áustria § 58c StbG. Extração ainda parcial — páginas 3 a 7 com campos não localizados, sem inferência.', 'Titulares/signatários: Ana Luiza Gomes Silveira Rodrigues (contratante), Adair Gomes Silveira e Alice Gomes Silveira. Dependente menor: Felipe, representado por Ana — representação pendente.', 9600.00, true, 'R$ 9.600,00 — referência interna pendente de formalização, espelhada do catálogo homologado PROD-DIAG-FAM-MULTI. Sem cobrança, parcela, link Asaas, contrato ou assinatura.', 'draft', NULL, NULL, 'Consolidação CORTE C. Aprovação bloqueada enquanto a conferência de escopo estiver bloqueada e a representação do dependente estiver pendente. Financeiro não liberado.', '2026-08-19 20:32:56.777632+00', NULL, '2026-08-20 13:56:56.165814+00', NULL, NULL, NULL, NULL);
INSERT INTO public.contract_templates VALUES
	('01114bbd-3923-44e0-bdf4-e42ca23f859f', '11f32aae-ea08-47e0-8114-f5d8a900c9a1', 'MODELO-ESTUDO', 'MODELO ESTUDO', 'contract_base', 'Versão contratual ativa para estudo de viabilidade e pesquisa genealógica.', 'active', 1, '{}', '[]', '{"modelo": "MODELO-ESTUDO + BASE-GEN-V2", "status": "under_legal_review", "versao": "v1.0", "clausulas": [{"itens": ["1.1. A qualificação completa da CONTRATADA será obtida exclusivamente do Perfil Institucional vigente e aprovado.", "1.2. A qualificação do(s) CONTRATANTE(S), signatário(s), beneficiário(s), representante(s) e dependente(s) será obtida dos parâmetros contratuais rastreáveis, da Ordem de Serviço/Proposta válida e dos anexos aplicáveis.", "1.3. Este Contrato-Base é complementado, quando aplicável, por: Ordem de Serviço ou Proposta Comercial aprovada, Anexo I — Ordem de Serviço, Anexo de Escopo, Anexo de Privacidade e Dados, Anexo Comercial, Anexo Individual e Anexo de Representação.", "1.4. Em caso de divergência específica entre este contrato-base e a Ordem de Serviço/Proposta aprovada, a Ordem de Serviço/Proposta prevalecerá quanto a escopo contratado, valores, forma de pagamento, parcelas, prazos específicos e despesas específicas, desde que respeitados o contrato-base, a legislação aplicável e as aprovações exigidas."], "numero": 1, "titulo": "Partes, documentos e estrutura do instrumento"}, {"itens": ["2.1. O presente instrumento tem por objeto a prestação de serviços técnicos especializados de pesquisa genealógica, organização de informações familiares, análise documental, estruturação de jornada documental e entregas descritas no escopo aprovado.", "2.2. Conforme a modalidade contratada, o serviço poderá incluir leitura de árvore existente, análise das informações e documentos fornecidos, identificação de lacunas e inconsistências, organização de hipóteses de pesquisa, definição de próximos passos, relatórios, orientação documental e demais entregas expressamente previstas no Anexo de Escopo.", "2.3. O objeto específico não transforma hipótese, narrativa, informação não validada ou triagem preliminar em fato comprovado, decisão jurídica, reconhecimento de direito ou garantia de resultado."], "numero": 2, "titulo": "Objeto"}, {"itens": ["3.1. Os serviços incluídos, entregas, fases, responsabilidades, limites, dependências, exclusões e marcos previstos estão descritos no Anexo I — Ordem de Serviço e na Ordem de Serviço/Proposta aprovada vinculada ao mesmo caso.", "3.2. Somente integra o escopo o que estiver expressamente indicado em fonte válida e aprovada. A ausência de previsão não será interpretada como inclusão tácita.", "3.3. Salvo contratação expressa e formalização aplicável, não estão incluídos: busca presencial em cartórios ou arquivos, solicitações institucionais externas, emissão de certidões, representação jurídica, protocolo perante órgãos, acompanhamento de processo de terceiros, tradução, apostilamento, retificação, deslocamento, custas e demais despesas externas.", "3.4. A inclusão de serviço adicional depende de escopo, condição comercial e aprovação formal aplicáveis."], "numero": 3, "titulo": "Escopo, entregas e exclusões"}, {"itens": ["4.1. Fornecer informações, documentos e autorizações disponíveis de modo fidedigno, legível e tempestivo.", "4.2. Informar corretamente nomes, datas, locais, vínculos familiares, alterações de estado civil, naturalizações, migrações, documentos e demais elementos relevantes de que tenha conhecimento.", "4.3. Comunicar alterações relevantes e responder às solicitações necessárias à execução do escopo.", "4.4. Efetuar os pagamentos dos honorários conforme condição formal aprovada.", "4.5. Obter, quando aplicável, autorização ou base legítima para compartilhar dados de terceiros e documentos familiares."], "numero": 4, "titulo": "Obrigações do(s) contratante(s)"}, {"itens": ["5.1. Executar os serviços de acordo com o escopo aprovado, a metodologia aplicável, as fontes disponíveis, os limites do caso e as normas de qualidade internas.", "5.2. Organizar e comunicar entregas ou atualizações contextualizadas conforme a jornada aplicável, sem assumir obrigação de resultado fora do escopo.", "5.3. Manter registro interno e controles proporcionais de segurança, acesso, fontes, versões e evidências, respeitando a legislação aplicável e as regras de visibilidade.", "5.4. Solicitar esclarecimentos, documentos ou aprovações adicionais quando necessários para continuidade, qualidade, segurança ou conformidade."], "numero": 5, "titulo": "Obrigações da contratada"}, {"itens": ["6.1. Os serviços têm natureza intelectual, técnica e metodológica. Resultados dependem, entre outros fatores, da existência, disponibilidade, legibilidade, acesso e validade de registros, atos de terceiros, órgãos, arquivos, cartórios, igrejas, consulados, autoridades e demais fontes externas.", "6.2. A CONTRATADA não garante localização de documento, confirmação de linhagem, reconhecimento de cidadania, emissão de documento, êxito perante autoridade, prazo de terceiro, continuidade de pesquisa, resultado de protocolo ou decisão jurídica.", "6.3. Triagem, radar, leitura inicial, hipótese de rota, referência jurídica, linha familiar, narrativa, informação de transcrição ou material recebido não substituem análise jurídica, prova documental, decisão administrativa ou judicial.", "6.4. Quando for necessária revisão especializada ou jurídica, a continuidade dependerá da regra de revisão aplicável e da aprovação humana competente."], "numero": 6, "titulo": "Limitações, hipóteses e ausência de garantia"}, {"itens": ["7.1. O tratamento de dados pessoais e documentos observará a finalidade contratual, o Anexo de Privacidade e Dados, a política vigente aplicável e a Lei nº 13.709/2018 — LGPD.", "7.2. A CONTRATADA adotará medidas técnicas e administrativas proporcionais para proteger os dados e documentos sob sua guarda contra acessos não autorizados, vazamentos, perda ou uso incompatível com a finalidade.", "7.3. A guarda, retenção, arquivamento e descarte observarão a política institucional versionada e vigente, os registros de aceite e eventuais obrigações legais aplicáveis. Nenhum prazo específico será presumido se não estiver previsto na política vigente.", "7.4. Gravações, transcrições e materiais de comunicação somente serão utilizados quando houver autorização, base aplicável e controles de acesso compatíveis."], "numero": 7, "titulo": "Documentos, privacidade, guarda e sigilo"}, {"itens": ["8.1. O valor, condição comercial, forma de pagamento, parcelas, vencimentos, responsável financeiro e condição de início serão os definidos na Ordem de Serviço/Proposta aprovada e nos parâmetros comerciais confirmados.", "8.2. O início de cada fase observará a condição formal aplicável, incluindo, quando previsto, pagamento inicial confirmado, documentos mínimos, autorizações, validação de escopo ou outros gates do caso.", "8.3. A existência de pagamento, contrato ou entrega não constitui garantia de resultado externo ou de reconhecimento de direito.", "8.4. Valores, preços e condições não poderão ser derivados de mensagem, transcrição, template, dado de demonstração ou preenchimento livre não aprovado."], "numero": 8, "titulo": "Valores, pagamento e início dos serviços"}, {"itens": ["9.1. Despesas de terceiros não estão incluídas nos honorários do Clube Ancestral. Serão comunicadas previamente e pagas diretamente pelo cliente, mediante aprovação registrada.", "9.2. Quando aplicável, a despesa deverá ter finalidade, fornecedor ou categoria, estimativa ou faixa quando disponível, responsável pagador e aprovação registrada antes de execução.", "9.3. Despesas de terceiros não constituem, por padrão, receita, custo próprio, desembolso, cobrança ou reembolso do Clube Ancestral.", "9.4. Exceções de antecipação, reembolso ou forma diversa exigem autorização formal, justificativa, aprovador, teto, validade e auditoria."], "numero": 9, "titulo": "Despesas de terceiros"}, {"itens": ["10.1. Os prazos de referência, marcos, dependências documentais e condições de ajuste aplicáveis ao caso estarão na Ordem de Serviço/Proposta aprovada e no Anexo I — Ordem de Serviço, quando formalmente definidos.", "10.2. Prazos podem ser impactados por atraso no envio de informações, necessidade de correção, indisponibilidade de registros, exigências de terceiros, espera institucional, revisão especializada, mudanças normativas ou outras dependências fora do controle da CONTRATADA.", "10.3. Não serão apresentadas estimativas automáticas como promessa de prazo institucional, jurídico ou de resultado."], "numero": 10, "titulo": "Prazo, dependências e ajustes"}, {"itens": ["11.1. Considera-se cumprida a etapa contratada com a entrega das atividades previstas no escopo aprovado, observados os critérios de aceite aplicáveis.", "11.2. A decisão do cliente de não continuar para etapa posterior não caracteriza, por si só, descumprimento da etapa já entregue.", "11.3. Entregas ao cliente ocorrerão apenas após aprovação interna, verificação de visibilidade e autorização compatível."], "numero": 11, "titulo": "Cumprimento, entregas e encerramento"}, {"itens": ["12.1. O cliente receberá os materiais e entregas nos limites definidos no escopo aprovado.", "12.2. Permanecem de titularidade da CONTRATADA seus métodos, modelos, sistemas, identidade visual, estruturas, prompts, processos, bibliotecas, bases e ativos preexistentes, sem prejuízo dos direitos do cliente sobre seus próprios documentos e dados, conforme legislação aplicável."], "numero": 12, "titulo": "Propriedade intelectual e materiais"}, {"itens": ["13.1. A assinatura ou aceite observará o método institucional homologado e os registros aplicáveis de data, responsável, origem e referência externa.", "13.2. A assinatura somente poderá ocorrer após a conclusão dos gates de escopo, dados das partes, anexos aplicáveis, condição comercial, revisão humana/jurídica e demais validações necessárias.", "13.3. O instrumento assinado, a Ordem de Serviço/Proposta vinculada e os anexos aplicáveis comporão a versão contratual rastreável."], "numero": 13, "titulo": "Assinatura, evidência e registros"}, {"itens": ["14.1. Este contrato será interpretado de acordo com a legislação brasileira e com as disposições de proteção ao consumidor aplicáveis.", "14.2. O foro e as disposições específicas serão os definidos na configuração jurídica institucional vigente, observadas as normas aplicáveis ao consumidor.", "14.3. Por estarem de acordo, as partes assinam o presente instrumento por meio físico ou eletrônico, conforme método institucional homologado."], "numero": 14, "titulo": "Disposições finais e foro"}], "preambulo": "Pelo presente instrumento, de um lado, a CONTRATADA, identificada no Perfil Institucional vigente do Clube Ancestral, e, de outro, o(s) CONTRATANTE(S) identificado(s) no cadastro, na Ordem de Serviço, na proposta aprovada e nos anexos aplicáveis, celebram o presente Contrato-Base de Prestação de Serviços Genealógicos e Jornada Documental, regido pelas cláusulas abaixo, pela Ordem de Serviço/Proposta aprovada, pelos anexos aplicáveis e pela legislação brasileira.", "contrato_base_id": "CA-CONTRATOS-Resgate-Consolidado-Contrato-Base-Motor-Anexos-v1.0", "perfil_institucional": [{"campo": "razao_empresarial", "valor": "TATIANA MELANI TOSI – ME", "rotulo": "Razão empresarial"}, {"campo": "nome_operacao", "valor": "Clube Ancestral", "rotulo": "Nome de operação"}, {"campo": "cnpj", "valor": "10.448.812/0001-58", "rotulo": "CNPJ"}, {"campo": "endereco_institucional", "valor": "Rua Nova York, 822, Apt. 142, Brooklin, CEP 04560-001, São Paulo – SP, Brasil", "rotulo": "Endereço institucional"}, {"campo": "email_oficial", "valor": "atendimento@clubeancestral.com.br", "rotulo": "E-mail oficial"}, {"campo": "site", "valor": "https://clubeancestral.com.br", "rotulo": "Site"}, {"campo": "whatsapp", "valor": "Canal institucional homologado/configurado — não inferir nem usar número pessoal", "rotulo": "WhatsApp"}, {"campo": "titulo", "valor": "CONTRATO DE SERVIÇOS DE PESQUISA GENEALÓGICA — CLUBE ANCESTRAL", "rotulo": "Título"}, {"campo": "subtitulo", "valor": "CONTRATO-BASE DE PRESTAÇÃO DE SERVIÇOS GENEALÓGICOS E JORNADA DOCUMENTAL", "rotulo": "Subtítulo"}], "perfil_institucional_versao": "PERFIL-INST-v1.0"}', '[]', true, NULL, NULL, NULL, NULL, false, '2026-08-16 23:29:35.007486+00', NULL, '2026-08-22 14:29:40.374291+00', NULL, NULL, NULL, NULL, 'geracao'),
	('d0d6ca0b-29bb-4209-bd01-cb6900afded8', '11f32aae-ea08-47e0-8114-f5d8a900c9a1', 'BASE-GEN-V2', 'Base contratual genérica v2', 'contract_base', 'Base contratual genérica v2, aplicável em conjunto com o MODELO ESTUDO.', 'active', 2, '{}', '[]', '{"modelo": "MODELO-ESTUDO + BASE-GEN-V2", "status": "under_legal_review", "versao": "v1.0", "clausulas": [{"itens": ["1.1. A qualificação completa da CONTRATADA será obtida exclusivamente do Perfil Institucional vigente e aprovado.", "1.2. A qualificação do(s) CONTRATANTE(S), signatário(s), beneficiário(s), representante(s) e dependente(s) será obtida dos parâmetros contratuais rastreáveis, da Ordem de Serviço/Proposta válida e dos anexos aplicáveis.", "1.3. Este Contrato-Base é complementado, quando aplicável, por: Ordem de Serviço ou Proposta Comercial aprovada, Anexo I — Ordem de Serviço, Anexo de Escopo, Anexo de Privacidade e Dados, Anexo Comercial, Anexo Individual e Anexo de Representação.", "1.4. Em caso de divergência específica entre este contrato-base e a Ordem de Serviço/Proposta aprovada, a Ordem de Serviço/Proposta prevalecerá quanto a escopo contratado, valores, forma de pagamento, parcelas, prazos específicos e despesas específicas, desde que respeitados o contrato-base, a legislação aplicável e as aprovações exigidas."], "numero": 1, "titulo": "Partes, documentos e estrutura do instrumento"}, {"itens": ["2.1. O presente instrumento tem por objeto a prestação de serviços técnicos especializados de pesquisa genealógica, organização de informações familiares, análise documental, estruturação de jornada documental e entregas descritas no escopo aprovado.", "2.2. Conforme a modalidade contratada, o serviço poderá incluir leitura de árvore existente, análise das informações e documentos fornecidos, identificação de lacunas e inconsistências, organização de hipóteses de pesquisa, definição de próximos passos, relatórios, orientação documental e demais entregas expressamente previstas no Anexo de Escopo.", "2.3. O objeto específico não transforma hipótese, narrativa, informação não validada ou triagem preliminar em fato comprovado, decisão jurídica, reconhecimento de direito ou garantia de resultado."], "numero": 2, "titulo": "Objeto"}, {"itens": ["3.1. Os serviços incluídos, entregas, fases, responsabilidades, limites, dependências, exclusões e marcos previstos estão descritos no Anexo I — Ordem de Serviço e na Ordem de Serviço/Proposta aprovada vinculada ao mesmo caso.", "3.2. Somente integra o escopo o que estiver expressamente indicado em fonte válida e aprovada. A ausência de previsão não será interpretada como inclusão tácita.", "3.3. Salvo contratação expressa e formalização aplicável, não estão incluídos: busca presencial em cartórios ou arquivos, solicitações institucionais externas, emissão de certidões, representação jurídica, protocolo perante órgãos, acompanhamento de processo de terceiros, tradução, apostilamento, retificação, deslocamento, custas e demais despesas externas.", "3.4. A inclusão de serviço adicional depende de escopo, condição comercial e aprovação formal aplicáveis."], "numero": 3, "titulo": "Escopo, entregas e exclusões"}, {"itens": ["4.1. Fornecer informações, documentos e autorizações disponíveis de modo fidedigno, legível e tempestivo.", "4.2. Informar corretamente nomes, datas, locais, vínculos familiares, alterações de estado civil, naturalizações, migrações, documentos e demais elementos relevantes de que tenha conhecimento.", "4.3. Comunicar alterações relevantes e responder às solicitações necessárias à execução do escopo.", "4.4. Efetuar os pagamentos dos honorários conforme condição formal aprovada.", "4.5. Obter, quando aplicável, autorização ou base legítima para compartilhar dados de terceiros e documentos familiares."], "numero": 4, "titulo": "Obrigações do(s) contratante(s)"}, {"itens": ["5.1. Executar os serviços de acordo com o escopo aprovado, a metodologia aplicável, as fontes disponíveis, os limites do caso e as normas de qualidade internas.", "5.2. Organizar e comunicar entregas ou atualizações contextualizadas conforme a jornada aplicável, sem assumir obrigação de resultado fora do escopo.", "5.3. Manter registro interno e controles proporcionais de segurança, acesso, fontes, versões e evidências, respeitando a legislação aplicável e as regras de visibilidade.", "5.4. Solicitar esclarecimentos, documentos ou aprovações adicionais quando necessários para continuidade, qualidade, segurança ou conformidade."], "numero": 5, "titulo": "Obrigações da contratada"}, {"itens": ["6.1. Os serviços têm natureza intelectual, técnica e metodológica. Resultados dependem, entre outros fatores, da existência, disponibilidade, legibilidade, acesso e validade de registros, atos de terceiros, órgãos, arquivos, cartórios, igrejas, consulados, autoridades e demais fontes externas.", "6.2. A CONTRATADA não garante localização de documento, confirmação de linhagem, reconhecimento de cidadania, emissão de documento, êxito perante autoridade, prazo de terceiro, continuidade de pesquisa, resultado de protocolo ou decisão jurídica.", "6.3. Triagem, radar, leitura inicial, hipótese de rota, referência jurídica, linha familiar, narrativa, informação de transcrição ou material recebido não substituem análise jurídica, prova documental, decisão administrativa ou judicial.", "6.4. Quando for necessária revisão especializada ou jurídica, a continuidade dependerá da regra de revisão aplicável e da aprovação humana competente."], "numero": 6, "titulo": "Limitações, hipóteses e ausência de garantia"}, {"itens": ["7.1. O tratamento de dados pessoais e documentos observará a finalidade contratual, o Anexo de Privacidade e Dados, a política vigente aplicável e a Lei nº 13.709/2018 — LGPD.", "7.2. A CONTRATADA adotará medidas técnicas e administrativas proporcionais para proteger os dados e documentos sob sua guarda contra acessos não autorizados, vazamentos, perda ou uso incompatível com a finalidade.", "7.3. A guarda, retenção, arquivamento e descarte observarão a política institucional versionada e vigente, os registros de aceite e eventuais obrigações legais aplicáveis. Nenhum prazo específico será presumido se não estiver previsto na política vigente.", "7.4. Gravações, transcrições e materiais de comunicação somente serão utilizados quando houver autorização, base aplicável e controles de acesso compatíveis."], "numero": 7, "titulo": "Documentos, privacidade, guarda e sigilo"}, {"itens": ["8.1. O valor, condição comercial, forma de pagamento, parcelas, vencimentos, responsável financeiro e condição de início serão os definidos na Ordem de Serviço/Proposta aprovada e nos parâmetros comerciais confirmados.", "8.2. O início de cada fase observará a condição formal aplicável, incluindo, quando previsto, pagamento inicial confirmado, documentos mínimos, autorizações, validação de escopo ou outros gates do caso.", "8.3. A existência de pagamento, contrato ou entrega não constitui garantia de resultado externo ou de reconhecimento de direito.", "8.4. Valores, preços e condições não poderão ser derivados de mensagem, transcrição, template, dado de demonstração ou preenchimento livre não aprovado."], "numero": 8, "titulo": "Valores, pagamento e início dos serviços"}, {"itens": ["9.1. Despesas de terceiros não estão incluídas nos honorários do Clube Ancestral. Serão comunicadas previamente e pagas diretamente pelo cliente, mediante aprovação registrada.", "9.2. Quando aplicável, a despesa deverá ter finalidade, fornecedor ou categoria, estimativa ou faixa quando disponível, responsável pagador e aprovação registrada antes de execução.", "9.3. Despesas de terceiros não constituem, por padrão, receita, custo próprio, desembolso, cobrança ou reembolso do Clube Ancestral.", "9.4. Exceções de antecipação, reembolso ou forma diversa exigem autorização formal, justificativa, aprovador, teto, validade e auditoria."], "numero": 9, "titulo": "Despesas de terceiros"}, {"itens": ["10.1. Os prazos de referência, marcos, dependências documentais e condições de ajuste aplicáveis ao caso estarão na Ordem de Serviço/Proposta aprovada e no Anexo I — Ordem de Serviço, quando formalmente definidos.", "10.2. Prazos podem ser impactados por atraso no envio de informações, necessidade de correção, indisponibilidade de registros, exigências de terceiros, espera institucional, revisão especializada, mudanças normativas ou outras dependências fora do controle da CONTRATADA.", "10.3. Não serão apresentadas estimativas automáticas como promessa de prazo institucional, jurídico ou de resultado."], "numero": 10, "titulo": "Prazo, dependências e ajustes"}, {"itens": ["11.1. Considera-se cumprida a etapa contratada com a entrega das atividades previstas no escopo aprovado, observados os critérios de aceite aplicáveis.", "11.2. A decisão do cliente de não continuar para etapa posterior não caracteriza, por si só, descumprimento da etapa já entregue.", "11.3. Entregas ao cliente ocorrerão apenas após aprovação interna, verificação de visibilidade e autorização compatível."], "numero": 11, "titulo": "Cumprimento, entregas e encerramento"}, {"itens": ["12.1. O cliente receberá os materiais e entregas nos limites definidos no escopo aprovado.", "12.2. Permanecem de titularidade da CONTRATADA seus métodos, modelos, sistemas, identidade visual, estruturas, prompts, processos, bibliotecas, bases e ativos preexistentes, sem prejuízo dos direitos do cliente sobre seus próprios documentos e dados, conforme legislação aplicável."], "numero": 12, "titulo": "Propriedade intelectual e materiais"}, {"itens": ["13.1. A assinatura ou aceite observará o método institucional homologado e os registros aplicáveis de data, responsável, origem e referência externa.", "13.2. A assinatura somente poderá ocorrer após a conclusão dos gates de escopo, dados das partes, anexos aplicáveis, condição comercial, revisão humana/jurídica e demais validações necessárias.", "13.3. O instrumento assinado, a Ordem de Serviço/Proposta vinculada e os anexos aplicáveis comporão a versão contratual rastreável."], "numero": 13, "titulo": "Assinatura, evidência e registros"}, {"itens": ["14.1. Este contrato será interpretado de acordo com a legislação brasileira e com as disposições de proteção ao consumidor aplicáveis.", "14.2. O foro e as disposições específicas serão os definidos na configuração jurídica institucional vigente, observadas as normas aplicáveis ao consumidor.", "14.3. Por estarem de acordo, as partes assinam o presente instrumento por meio físico ou eletrônico, conforme método institucional homologado."], "numero": 14, "titulo": "Disposições finais e foro"}], "preambulo": "Pelo presente instrumento, de um lado, a CONTRATADA, identificada no Perfil Institucional vigente do Clube Ancestral, e, de outro, o(s) CONTRATANTE(S) identificado(s) no cadastro, na Ordem de Serviço, na proposta aprovada e nos anexos aplicáveis, celebram o presente Contrato-Base de Prestação de Serviços Genealógicos e Jornada Documental, regido pelas cláusulas abaixo, pela Ordem de Serviço/Proposta aprovada, pelos anexos aplicáveis e pela legislação brasileira.", "contrato_base_id": "CA-CONTRATOS-Resgate-Consolidado-Contrato-Base-Motor-Anexos-v1.0", "perfil_institucional": [{"campo": "razao_empresarial", "valor": "TATIANA MELANI TOSI – ME", "rotulo": "Razão empresarial"}, {"campo": "nome_operacao", "valor": "Clube Ancestral", "rotulo": "Nome de operação"}, {"campo": "cnpj", "valor": "10.448.812/0001-58", "rotulo": "CNPJ"}, {"campo": "endereco_institucional", "valor": "Rua Nova York, 822, Apt. 142, Brooklin, CEP 04560-001, São Paulo – SP, Brasil", "rotulo": "Endereço institucional"}, {"campo": "email_oficial", "valor": "atendimento@clubeancestral.com.br", "rotulo": "E-mail oficial"}, {"campo": "site", "valor": "https://clubeancestral.com.br", "rotulo": "Site"}, {"campo": "whatsapp", "valor": "Canal institucional homologado/configurado — não inferir nem usar número pessoal", "rotulo": "WhatsApp"}, {"campo": "titulo", "valor": "CONTRATO DE SERVIÇOS DE PESQUISA GENEALÓGICA — CLUBE ANCESTRAL", "rotulo": "Título"}, {"campo": "subtitulo", "valor": "CONTRATO-BASE DE PRESTAÇÃO DE SERVIÇOS GENEALÓGICOS E JORNADA DOCUMENTAL", "rotulo": "Subtítulo"}], "perfil_institucional_versao": "PERFIL-INST-v1.0"}', '[]', true, NULL, NULL, NULL, NULL, false, '2026-08-16 23:29:35.007486+00', NULL, '2026-08-22 14:29:40.374291+00', NULL, NULL, NULL, NULL, 'geracao');
